	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;
	var y;
	var z;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	x = new ndarray( 'float64', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	ybuf = new Float64Array( [ 5.0, 6.0, 7.0, 8.0 ] );
	y = new ndarray( 'float64', ybuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );

	z = zeros( [ 2, 4 ], {
		'dtype': 'float32'
	});

